import {sampleCode,barcodeRules,skuFor} from './barcodes.js';
import {ContinuousScanner} from './camera.js';
import {traceLot,traceNodes} from './trace.js';
import {seed,kinds,DAY,quantity,daysLeft,scan,undo,saveAllocation,confirm,changeLot,notify,log} from './engine.js';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]));
const paths={home:'M3 10 12 3l9 7M5 9v12h5v-7h4v7h5V9',box:'m3 7 9-4 9 4v10l-9 4-9-4ZM3 7l9 4 9-4M12 11v10M7 5l9 4',in:'M4 14v6h16v-6M12 3v12m-5-5 5 5 5-5',out:'M4 14v6h16v-6M12 15V3m-5 5 5-5 5 5',scan:'M8 3H3v5m13-5h5v5M3 16v5h5m13-5v5h-5M7 7v10m4-10v10m3-10v10m3-10v10',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4',tasks:'M9 4H5v17h14V4h-4M9 2h6v4H9ZM8 11h8m-8 5h5',stock:'M3 9l9-6 9 6v12H3ZM8 21v-8h8v8M3 9h18',leaf:'M20 3C7 2 2 7 5 15s16 5 15-12ZM4 21 15 10',layers:'m3 7 9-5 9 5-9 5ZM3 12l9 5 9-5M3 17l9 5 9-5',chevron:'m9 5 7 7-7 7',back:'m15 5-7 7 7 7',check:'m5 12 4 4L19 6',close:'m6 6 12 12M6 18 18 6',pin:'M19 9c0 5-7 12-7 12S5 14 5 9a7 7 0 0 1 14 0ZM9 9a3 3 0 1 0 6 0 3 3 0 0 0-6 0',clock:'M12 7v5l3 2M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0',search:'M21 21l-6-6M17 10a7 7 0 1 1-14 0 7 7 0 0 1 14 0',history:'M3 4v5h5M3 9a9 9 0 1 1 0 6M12 7v5l3 2',info:'M12 11v6M12 7h.01M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0',warning:'m12 3 10 18H2ZM12 9v5m0 3h.01',sync:'M20 7a9 9 0 0 0-15-2L2 8m0-5v5h5M4 17a9 9 0 0 0 15 2l3-3m0 5v-5h-5',sun:'M12 1v2m0 18v2M1 12h2m18 0h2M4 4l2 2m12 12 2 2M4 20l2-2M18 6l2-2M17 12a5 5 0 1 1-10 0 5 5 0 0 1 10 0',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M9 3h6l1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1Z',truck:'M2 5h12v12H2ZM14 9h4l4 4v4h-8M7 19a2 2 0 1 0-4 0 2 2 0 0 0 4 0m14 0a2 2 0 1 0-4 0 2 2 0 0 0 4 0',wifi:'M2 8q10-9 20 0M5 12q7-6 14 0m-10 4q3-3 6 0M12 20h.01'};
const icon=(n,cls='')=>`<svg class="ico ${cls}" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.box}"/></svg>`;
let state;try{const saved=JSON.parse(localStorage.getItem('malgeun-field-v2'));state=saved?.version===2&&Array.isArray(saved.tasks)&&saved.tasks.length===7?saved:seed();}catch{state=seed();}
let screen='home',activeTask=state.tasks[0].id,activeStock='P1',taskFilter='all',kindFilter='P',stockKind='all',stockWarehouse='전체 창고',noticeFilter='all',query='',modal='',scanMessage='',scanError=false,toastTimer,focusBeforeModal=null;
let cameraSession=null, cameraStatus='카메라 대기',traceQuery='RM-261020',traceDirection='both',traceNodeId='raw-in';
const getTask=()=>state.tasks.find(x=>x.id===activeTask),getStock=t=>state.stocks.find(x=>x.id===(t?.stockId||activeStock)),fmt=n=>Number(n).toLocaleString('ko-KR'),persist=()=>{try{localStorage.setItem('malgeun-field-v2',JSON.stringify(state));}catch{}};
const stateLabel=t=>({waiting:'검수 대기',progress:'검수 중',saved:'ERP 등록 · 확정 대기',done:'처리 완료'}[t.state]);
const btn=(action,text,cls='',attrs='')=>`<button data-action="${action}" class="${cls}" ${attrs}>${text}</button>`;
const workDescriptions={M:'원료창고 · kg 중량 확인 → 입출고 확정',S:'부자재창고 · 포장수량 확인 → 입출고 확정',P:'제품창고 · 차량·LOT 검수 → 출고 확정'};
const locations=t=>t.direction==='in'?['입고 대기구역','검수구역','보관구역']:t.kind==='P'?['출고 피킹구역','상차 대기구역']:['보관구역','작업장 인계구역'];
const badge=t=>`<span class="task-type ${kinds[t.kind].color}">${kinds[t.kind].name} · ${t.direction==='in'?'입고':'출고'}</span>`;
function toast(text,error=false){$('#toast').textContent=text;$('#toast').className='show'+(error?' error':'');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').className='',3600);}
function openModal(type){focusBeforeModal=document.activeElement;modal=type;renderModal();const focus=$('#modal-root button');focus?.focus();}
function closeModal(){stopCamera();modal='';renderModal();if(focusBeforeModal?.isConnected)focusBeforeModal.focus();}
function go(next){stopCamera();screen=next;modal='';query='';render();$('#app-content').scrollTop=0;if(location.hash!=='#'+next)history.replaceState(null,'','#'+next);}
function openTask(id){activeTask=id;kindFilter=getTask().kind;go('detail');}
function kindTabs(value,action,all='전체'){return `<div class="chip-tabs">${(action==='stock-kind'?['all','M','S','P']:['M','S','P']).map(k=>btn(action,k==='all'?all:kinds[k].name,k===value?'selected':'',`data-value="${k}"`)).join('')}</div>`;}
function taskCard(t){const s=getStock(t);return `<button class="task-card" data-action="task" data-id="${t.id}" aria-label="${esc(t.title)} 작업 열기"><div class="task-card-top">${badge(t)}${(state.holds||[]).includes(s.lot)?'<span class="quality-hold-badge">품질 보류</span>':''}<span class="task-due ${t.state==='done'?'done':''}">${t.state==='done'?'✓ 완료':t.time+' 예정'}</span></div><h4>${esc(t.title)}</h4><p>${esc(t.id)} · ${esc(s.warehouse)}</p><div class="task-card-bottom"><span>${t.vehicle?icon('truck')+' '+esc(t.vehicle):esc(t.party)}</span><b>${fmt(t.qty)} ${s.unit} ${icon('chevron')}</b></div></button>`;}
function home(){const pending=state.tasks.filter(t=>t.state!=='done'&&t.kind===kindFilter),complete=state.tasks.filter(t=>t.kind===kindFilter&&t.state==='done').length,shown=pending.filter(x=>kindFilter==='all'||x.kind===kindFilter).slice(0,2);return `<div class="greeting-top"><div><p class="date">2026년 10월 26일 월요일</p><h2>안녕하세요, <b>김현장님</b><br>오늘도 안전한 작업 하세요.</h2></div><div class="weather">${icon('sun')}<span>맑음</span></div></div>${workPicker()}${btn('warehouse',icon('pin')+' 맑은물에 · 제1사업장 <span>⌄</span>','location-button')}<section class="today-card"><div class="today-top"><span>${icon('tasks')} 오늘의 작업</span><small>ERP 지시 기준</small></div><div class="today-numbers"><b>${pending.length}</b><span>건의 작업이 기다리고 있어요</span></div><div class="today-bottom"><span>입고 대기 <b>${pending.filter(t=>t.direction==='in').length}건</b></span><span>출고 대기 <b>${pending.filter(t=>t.direction==='out').length}건</b></span><span>처리 완료 <b>${complete}건</b></span></div></section><div class="section-title"><h3>빠른 작업</h3><span class="header-tag">DEMO</span></div><div class="quick-grid">${[['in-list','in','입고 관리'],['out-list','out','출고 관리'],['stock','stock','재고 조회'],['trace','layers','LOT 추적']].map(([a,i,t])=>btn(a,`<span>${icon(i)}</span>${t}`,'quick-btn')).join('')}</div><div class="section-title"><h3>지금 확인할 작업 <span style="font-size:10px;color:#5e9881;margin-left:4px">${pending.length}</span></h3>${btn('tasks','전체 보기 ›')}</div>${shown.length?shown.map(taskCard).join(''):`<div class="empty">${icon('check')}<br>남은 작업이 없어요<p>다른 분류를 선택하거나 작업 이력을 확인하세요.</p></div>`}${btn('notices',icon('clock')+'<span>소비기한 임박 LOT를 확인해 주세요</span>'+icon('chevron'),'alert-ribbon')}<p class="app-demo-note">ERP 업무 기반 · 가상 데이터로 동작하는 데모</p>`;}
function tasks(){const rows=state.tasks.filter(t=>(taskFilter==='all'||t.direction===taskFilter)&&(kindFilter==='all'||t.kind===kindFilter)&&(t.title+t.id+t.party).toLowerCase().includes(query.toLowerCase()));return `<div class="list-top"><h2>입출고 작업</h2><span>10월 26일 · 월</span></div><div class="segmented">${[['all','전체 작업'],['in','입고'],['out','출고']].map(([v,n])=>btn('task-filter',n,taskFilter===v?'selected':'',`data-value="${v}"`)).join('')}</div>${kindTabs(kindFilter,'task-kind')}<label class="search-box">${icon('search')}<input id="task-search" aria-label="작업 검색" placeholder="작업명, 지시번호, 거래처 검색" value="${esc(query)}"></label><div class="list-subhead"><strong>총 ${rows.length}건</strong><span>ERP 지시 수신 완료</span></div><div id="task-results">${rows.map(taskCard).join('')||'<div class="empty">검색 결과가 없습니다.</div>'}</div>`;}
function detail(){const t=getTask(),s=getStock(t),q=quantity(t);if(t.state==='done')return result(t,s);const pOut=t.kind==='P'&&t.direction==='out';return `<div class="detail-banner">${badge(t)}<small>${esc(t.id)}</small></div>${stepper(t)}${t.direction==='out'&&(state.holds||[]).includes(s.lot)?'<div class="hint warning">품질 검토 중인 LOT입니다. 관련 출고가 보류되었습니다.</div>':''}<h2 class="detail-title">${esc(t.title)}</h2><p class="detail-subtitle">${esc(t.party)} · ${esc(t.source)}</p><section class="info-card"><h3>${kinds[t.kind].name} ${t.direction==='in'?'입고 확인':'출고 지시'}</h3><div class="workflow-brief">${workDescriptions[t.kind]}</div><div class="info-row"><span>작업 위치 (제안)</span><select id="location-select" aria-label="작업 위치" ${t.allocated?'disabled':''}>${locations(t).map(x=>`<option ${t.location===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="info-row"><span>작업 창고</span><b>${s.warehouse}</b></div>${t.vehicle?`<div class="info-row"><span>배차 차량</span><select id="vehicle-select" aria-label="배차 차량" ${t.allocated?'disabled':''}><option ${t.vehicle.startsWith('1')?'selected':''}>1호차 · 12가 3456</option><option ${t.vehicle.startsWith('2')?'selected':''}>2호차 · 34나 5678</option></select></div><div class="info-row"><span>차량 온도</span><b><input id="vehicle-temp" aria-label="차량 온도" type="number" min="-30" max="50" step="0.1" value="${esc(t.temp)}" ${t.allocated?'disabled':''}> ℃</b></div>`:`<div class="info-row"><span>입출고 예정</span><b>2026.10.26 · ${t.time}</b></div>`}<div class="info-row"><span>지시 수량</span><b>${fmt(t.qty)} ${s.unit}</b></div><div class="lot-box"><div class="lot-label"><span>선택한 LOT</span>${pOut&&!t.allocated?btn('lot-picker','변경','link-btn'):''}</div><strong>${esc(s.lot)}</strong><div class="lot-bottom"><span>${s.expiry?'소비기한 '+s.expiry.replaceAll('-','.'):'소비기한 관리 대상 아님'}</span><span>가용 ${fmt(s.stock)} ${s.unit}</span></div></div>${pOut&&s.id==='P1'?'<div class="expiry-hint">ⓘ 소비기한이 더 빠른 LOT가 있습니다. LOT 선택에서 확인하세요.</div>':''}</section><section class="info-card"><h3>${esc(s.name)}</h3><div class="progress-heading"><span>검수 수량 · ${esc(s.spec)}</span><div><strong>${fmt(q)}</strong><small>/ ${fmt(t.qty)} ${s.unit}</small></div></div><div class="progress-track"><div style="width:${q/t.qty*100}%"></div></div><div class="progress-text"><span>${q===t.qty?'✓ 지시 수량과 일치해요':`남은 수량 ${fmt(t.qty-q)} ${s.unit}`}</span><span>${t.scans.length}건 스캔 검수</span></div></section>${!t.allocated?btn('scan',icon('scan')+' 연속 스캔 시작','scan-launch'):('<div class="saved-badge">'+icon('check')+' ERP 내역이 저장되었습니다</div>')}${t.scans.length?`<div class="section-title"><h3>스캔 보관함 <span style="color:#78a085">${t.scans.length}</span></h3>${!t.allocated?btn('undo','최근 스캔 취소'):''}</div><div class="info-card">${t.scans.map(x=>`<div class="scan-record">${icon('check')}<div>${esc(x.code)}<small>${esc(s.lot)}</small></div><b>+${x.qty} ${s.unit}</b></div>`).join('')}</div>`:''}${t.direction==='in'?`<label class="quality-check"><input id="quality-check" type="checkbox" ${t.quality?'checked':''}><span><b>입고 품질 확인</b><br>외관·수량·표시사항을 확인했습니다. (데모 체크리스트)</span></label>`:''}<div class="hint">${icon('info')}<span>${pOut?'완제품은 차량·LOT 출고 내역을 저장할 때 재고가 차감됩니다. 다음 출고 확정에서 재고를 다시 차감하지 않습니다.':t.direction==='in'?'입고 내역을 등록한 뒤 품질 확인 후 입고 확정하면 선택 창고·LOT 재고가 증가합니다.':'출고 내역 등록 시 재고는 유지됩니다. 출고 확정 시 선택 창고·LOT 재고를 차감합니다.'}</span></div><div class="detail-actions">${!t.allocated?btn('save',pOut?'스캔 일괄 등록 · 재고 반영':'스캔 일괄 등록','action-primary',q!==t.qty?'disabled':''):btn('confirm-open',t.direction==='in'?'입고 확정':'출고 확정','action-primary',t.direction==='in'&&!t.quality?'disabled':'')}<p class="micro-note">${t.allocated?'내역 저장 완료 · ERP 확정 전입니다.':'스캔 중에는 가상 ERP 재고가 변경되지 않습니다.'}</p></div>`;}
function result(t,s){return `<section class="result-view"><div class="success-circle">${icon('check')}</div><h2>${t.direction==='in'?'입고':'출고'}가 완료되었어요</h2><p>검수 결과가 ERP에 반영되었습니다.<br>수고하셨습니다, 김현장님.</p><div class="info-card"><div class="result-row"><span>지시번호</span><b>${t.id}</b></div><div class="result-row"><span>품목</span><b>${esc(s.name)}</b></div><div class="result-row"><span>LOT</span><b>${s.lot}</b></div><div class="result-row"><span>처리 수량</span><b>${fmt(t.qty)} ${s.unit}</b></div><div class="result-row"><span>현재 재고</span><b>${fmt(s.stock)} ${s.unit}</b></div><div class="result-row"><span>ERP 상태</span><b>✓ ${t.direction==='in'?'입고':'출고'} 확정</b></div><div class="result-row"><span>완료 시각</span><b>2026.10.26 · ${t.completedAt}</b></div></div>${btn('tasks','작업 목록으로','action-primary')}${btn('erp',icon('sync')+' ERP 반영 내역 보기','secondary-btn','style="margin-top:10px"')}<p class="micro-note">완료된 작업은 중복 반영되지 않습니다.</p></section>`;}
function stockList(){const filtered=state.stocks.filter(s=>(stockKind==='all'||s.kind===stockKind)&&(stockWarehouse==='전체 창고'||s.warehouse===stockWarehouse)&&(s.name+s.lot+s.item).toLowerCase().includes(query.toLowerCase()));return `<div class="list-top"><h2>재고 조회</h2><span>창고 · 품목 · LOT 기준</span></div><div class="stock-summary"><div><small>관리 중인 LOT</small><strong>${state.stocks.length}<span>건</span></strong></div><div><small>소비기한 임박</small><strong>${state.stocks.filter(s=>daysLeft(s.expiry)!==null&&daysLeft(s.expiry)>=0&&daysLeft(s.expiry)<=7).length}<span>건</span></strong></div><div><small>기준 재고 미달</small><strong>${state.stocks.filter(s=>s.stock<s.threshold).length}<span>건</span></strong></div></div>${kindTabs(stockKind,'stock-kind')}<label class="search-box">${icon('search')}<input id="stock-search" aria-label="재고 검색" placeholder="품목명, 품목코드, LOT 검색" value="${esc(query)}"></label><div class="list-subhead"><strong>총 ${filtered.length}개 LOT</strong><select id="stock-warehouse" aria-label="재고 창고 필터">${['전체 창고','원료창고','부자재창고','제품냉장창고'].map(w=>`<option ${w===stockWarehouse?'selected':''}>${w}</option>`).join('')}</select></div><div id="stock-results">${filtered.map(stockCard).join('')||'<div class="empty">검색 결과가 없습니다.</div>'}</div><p class="micro-note">임박·재고 알림 기준은 시연용 신규 제안 정책입니다.</p>`;}
function stockCard(s){const d=daysLeft(s.expiry);return `<button class="stock-card" data-action="stock-detail" data-id="${s.id}"><div class="stock-card-head"><span class="task-type ${kinds[s.kind].color}">${kinds[s.kind].name}</span>${d!==null&&d<0?'<span class="stock-warning expired">소비기한 경과</span>':d!==null&&d<=7?`<span class="stock-warning">소비기한 D-${d}</span>`:s.stock<s.threshold?'<span class="stock-warning">기준 재고 미달</span>':''}</div><h4>${esc(s.name)}</h4><p>${s.lot}</p><div class="stock-bottom"><span>${s.warehouse}</span><b>${fmt(s.stock)} <small>${s.unit}</small></b></div></button>`;}
function stockDetail(){const s=getStock();return `<div class="stock-hero">${icon(kinds[s.kind].icon)}<h2>${esc(s.name)}</h2><small>${s.item} · ${esc(s.spec)}</small><strong>${fmt(s.stock)}<em>${s.unit}</em></strong></div><div class="info-card"><h3>LOT 재고 정보</h3>${[['품목 구분',kinds[s.kind].name],['보관 창고',s.warehouse],['LOT 번호',s.lot],['소비기한',s.expiry||'해당 없음'],['시연 시작 재고',`${s.initial} ${s.unit}`],['현재 재고',`${s.stock} ${s.unit}`],['알림 기준 (제안)',`${s.threshold} ${s.unit}`]].map(([a,b])=>`<div class="info-row"><span>${a}</span><b>${esc(b)}</b></div>`).join('')}</div>${daysLeft(s.expiry)!==null&&daysLeft(s.expiry)<=7?`<div class="hint warning">${icon('warning')}<span>${daysLeft(s.expiry)<0?'소비기한이 경과한 LOT입니다. 출고를 차단합니다.':`소비기한이 ${daysLeft(s.expiry)}일 남았습니다. 먼저 출고할 LOT를 확인해 주세요.`}</span></div>`:''}${btn('trace-stock',icon('layers')+' 이 LOT 추적하기','action-primary')}${btn('stock','재고 목록으로','secondary-btn','style="margin-top:10px"')}<p class="micro-note">조회 기준일은 2026.10.26으로 고정됩니다.</p>`;}
const noticeType={task:{label:'작업 지시',icon:'tasks',color:'teal'},expiry:{label:'소비기한',icon:'clock',color:'amber'},error:{label:'검수 오류',icon:'warning',color:'amber'},stock:{label:'재고 알림',icon:'stock',color:'blue'},complete:{label:'ERP 완료',icon:'check',color:'teal'}};
function notices(){const unread=state.notices.filter(n=>!n.read).length,rows=state.notices.filter(n=>noticeFilter!=='unread'||!n.read);return `<div class="notice-toolbar"><strong>알림함 <span style="font-size:12px;color:#228d77">${unread}</span></strong>${btn('read-all','모두 읽음')}</div><div class="segmented">${btn('notice-filter','전체 알림',noticeFilter==='all'?'selected':'','data-value="all"')}${btn('notice-filter','읽지 않음',noticeFilter==='unread'?'selected':'','data-value="unread"')}</div>${rows.length?rows.map(n=>{const c=noticeType[n.type];return `<button class="notice-card ${!n.read?'unread':''}" data-action="notice" data-id="${n.id}"><span class="notice-icon ${c.color}">${icon(c.icon)}</span><div><div class="notice-top"><span>${c.label}${!n.read?'<i class="unread-dot"></i>':''}</span><time>${n.time}</time></div><h4>${esc(n.title)}</h4><p>${esc(n.body)}</p></div></button>`;}).join(''):`<div class="empty">${icon('bell')}<br>새로운 알림이 없어요</div>`}<div class="hint">${icon('info')}<span>작업 지시·검수 오류·ERP 완료를 앱 안에서 알립니다. 브라우저를 닫은 상태의 푸시는 연결하지 않았습니다.</span></div>${btn('simulate-notice','새 작업 알림 시연','secondary-btn')}`;}
function historyPage(){return `<div class="list-top"><h2>작업 이력</h2><span>완료 ${state.history.length}건</span></div>${state.history.map(h=>`<button class="history-item" data-action="task" data-id="${h.id}"><span class="task-type ${kinds[h.kind].color}">${kinds[h.kind].name} · ${h.direction==='in'?'입고':'출고'}</span><strong>✓ ERP 반영</strong><h4>${esc(h.title)}</h4><p>${h.id} · ${h.time}<br>${h.lot} · ${h.qty} ${h.unit}</p></button>`).join('')||`<div class="empty">${icon('history')}<br>완료한 작업이 여기에 표시됩니다.<p>입출고 작업을 검수하고 ERP에 반영해 보세요.</p></div>`}${btn('erp','ERP 처리 타임라인 보기','secondary-btn')}`;}
function erpPage(){return `<div class="list-top"><h2>ERP 반영 내역</h2><span>가상 연동</span></div><div class="hint">${icon('sync')}<span>실제 API 호출 없이 ERP 처리 시점과 재고 변화를 시뮬레이션합니다.</span></div>${state.events.map(e=>`<article class="app-erp-log"><time>${e.time}</time><h4>${esc(e.title)}</h4><p>${esc(e.body)}</p></article>`).join('')}`;}
function settings(){return `<div class="list-top"><h2>내 작업 설정</h2><span>시연 계정</span></div><div class="settings-card"><div class="setting-row"><div><b>김현장 · 물류 담당자</b><p>맑은물에 제1사업장<br>데모 로그인 상태 · 실제 인증 연결 없음</p></div><span class="user-avatar">김</span></div></div><div class="settings-card"><div class="setting-row"><div><b>앱 알림 받기</b><p>활성화하면 새 이벤트를 안 읽은 알림으로 표시합니다.</p></div>${btn('toggle-alerts','<span></span>','toggle '+(state.settings.alerts?'on':''),`aria-label="앱 알림 받기" aria-pressed="${state.settings.alerts}"`)}</div></div>${btn('simulate-notice',icon('bell')+' 새 작업 알림 시연','secondary-btn')}<div class="spacer"></div>${btn('rules',icon('scan')+' 라벨·수량 기준','secondary-btn')}<div class="spacer"></div>${btn('trace',icon('layers')+' LOT 추적','secondary-btn')}<div class="spacer"></div>${btn('open-design',icon('info')+' ERP 로직 · 앱 설계 보기','secondary-btn')}<div class="spacer"></div>${btn('history',icon('history')+' 작업 이력','secondary-btn')}<div class="spacer"></div><a class="secondary-btn" href="source.zip" download>소스 코드 다운로드 ↗</a><div class="spacer"></div>${btn('reset','시연 데이터 초기화','secondary-btn')}<p class="micro-note">시연 상태는 이 기기 브라우저에만 저장됩니다.<br>앱을 새로고침해도 작업 상태가 유지됩니다.</p>`;}
function renderHeader(){const title={trace:'LOT 추적',rules:'라벨·수량 기준',home:'',tasks:'입출고 작업',detail:'작업 상세',stock:'재고 조회','stock-detail':'LOT 재고 상세',notices:'알림',history:'작업 이력',erp:'ERP 반영 내역',settings:'설정'}[screen]||'';const unread=state.notices.filter(x=>!x.read).length;$('#app-header').innerHTML=screen==='home'?`<div class="app-brand">맑은물에 <small>FIELD</small></div><span class="header-spacer"></span>${btn('notices',icon('bell')+(unread?`<i class="notification-count">${unread>9?'9+':unread}</i>`:''),'icon-btn','aria-label="알림함 열기"')}${btn('settings','김','user-avatar','aria-label="내 작업 설정"')}`:`${btn('back',icon('back'),'icon-btn','aria-label="뒤로"')}<span class="screen-title">${title}</span><span class="header-spacer"></span>${btn('notices',icon('bell')+(unread?`<i class="notification-count">${unread>9?'9+':unread}</i>`:''),'icon-btn','aria-label="알림함 열기"')}`;}
function renderNav(){const current=screen==='trace'?'stock':screen==='rules'?'settings':screen==='detail'?'tasks':screen==='stock-detail'?'stock':screen;$('#bottom-nav').innerHTML=[['home','home','홈'],['tasks','tasks','작업'],['scan','scan','스캔'],['stock','stock','재고'],['notices','bell','알림']].map(([a,i,t])=>a==='scan'?btn(a,icon(i)+'<span class="scan-label">스캔</span>','scan-nav','aria-label="바코드 스캔"'):btn(a,icon(i)+(a==='notices'&&state.notices.some(n=>!n.read)?'<i class="nav-badge"></i>':'')+`<span>${t}</span>`,current===a?'active':'',`aria-label="${t} 메뉴"`)).join('');}
function renderObserver(){const t=getTask(),s=getStock(t);$('#observer').innerHTML=`<section class="observer-card"><div class="overline">CURRENT ORDER ${icon('tasks')}</div><h3>${t.id}</h3><span class="observer-state">${stateLabel(t)}</span><div class="observer-steps">${[['waiting','작업 수신'],['progress','바코드 검수'],['saved','내역 저장'],['done','확정 완료']].map(([key,label],i)=>`<span class="${['waiting','progress','saved','done'].indexOf(t.state)>=i?'passed':''}">${label}</span>`).join('')}</div><div class="observer-row"><span>구분 / 처리</span><b>${kinds[t.kind].name} · ${t.direction==='in'?'입고':'출고'}</b></div><div class="observer-row"><span>창고 / LOT</span><b>${s.warehouse}<br>${s.lot}</b></div><div class="observer-row"><span>ERP 재고</span><b>${s.initial}<span style="color:#9fb2a4;margin:0 6px">→</span><em>${fmt(s.stock)} ${s.unit}</em></b></div></section><div class="log-label">연동 타임라인 <span>RECENT ${Math.min(state.events.length,5)}</span></div>${state.events.slice(0,5).map(e=>`<article class="observer-log ${e.type}"><time>${e.time}</time><b>${esc(e.title)}</b><p>${esc(e.body)}</p></article>`).join('')}<div class="observer-caption"><b>왜 저장과 확정이 나뉘나요?</b><br>완제품은 LOT 출고 내역 저장 시 재고 차감,<br>원자재·부자재는 출고 확정 시 재고 차감.<br>로컬 ERP에서 확인한 처리 시점을 반영했습니다.<br>${btn('open-design','ERP 로직 반영 내용 보기 ↗')}</div>`;}
function render(){renderHeader();$('#app-content').innerHTML=({home,tasks,detail,stock:stockList,'stock-detail':stockDetail,notices,history:historyPage,erp:erpPage,settings,trace:tracePage,rules:rulesPage}[screen]||home)();renderNav();renderObserver();renderModal();persist();}
function renderModal(){if(!modal){$('#modal-root').innerHTML='';return;}const t=getTask(),s=getStock(t),close=btn('close-modal',icon('close'),'','aria-label="닫기"');let body='';if(modal==='scan'){body=scanSheet(t,s,close);}
 else if(modal==='lot'){const options=state.stocks.filter(x=>x.item===s.item&&x.kind===s.kind);body=`<div class="sheet-heading"><h2>출고 LOT 선택</h2>${close}</div><p>소비기한과 가용 재고를 확인하세요.<br>LOT 변경 시 현재 스캔 내역은 초기화됩니다.</p>${options.sort((a,b)=>(a.expiry||'').localeCompare(b.expiry||'')).map(x=>btn('select-lot',`<strong>${x.lot}</strong><span>${x.stock} ${x.unit}</span><p>${x.warehouse} · 소비기한 ${x.expiry}</p>`, 'lot-option '+(x.id===s.id?'selected':''),`data-id="${x.id}"`)).join('')}<div class="hint warning">${icon('info')}<span>소비기한 우선 출고는 신규 제안 정책입니다.<br>실제 ERP의 LOT 선택을 강제로 제한하지 않습니다.</span></div>`;}
 else if(modal==='confirm'){body=`<div class="sheet-heading"><h2>${t.direction==='in'?'입고':'출고'}를 확정할까요?</h2>${close}</div><p>${esc(s.name)} <b>${t.qty} ${s.unit}</b><br>${s.warehouse} · ${s.lot}</p><div class="inline-stat"><span>확정 후 ERP 재고</span><b>${fmt(t.direction==='in'?s.stock+t.qty:t.kind==='P'?s.stock:s.stock-t.qty)} ${s.unit}</b></div><p>${t.kind==='P'&&t.direction==='out'?'내역 저장 시 차감된 재고를 유지하고 출고확정 및 단가 기록을 처리합니다.':'선택 창고·LOT 재고와 입출고 상태를 반영합니다.'}<br>완료 후에는 이 데모에서 작업을 취소할 수 없습니다.</p>${btn('confirm','확정 · ERP에 반영','action-primary')}`;}
 else if(modal==='warehouse'){body=`<div class="sheet-heading"><h2>사업장 · 창고</h2>${close}</div><p>이 시연은 제1사업장 기준입니다.<br>창고를 선택하면 해당 창고 재고로 이동합니다.</p>${['원료창고','부자재창고','제품냉장창고'].map(w=>btn('warehouse-stock',`<div>${w}<small>맑은물에 · 제1사업장</small></div>${icon('chevron')}`,'warehouse-option',`data-value="${w}"`)).join('')}`;}
 else if(modal==='trace-node'){const n=traceNodes.find(x=>x.id===traceNodeId);body=`<div class="sheet-heading"><h2>${n.title}</h2>${close}</div><span class="task-type ${kinds[n.kind].color}">${kinds[n.kind].name} · ${n.department}</span><h3>${n.item}</h3><div class="info-card">${[['LOT',n.lot],['기록번호',n.record],['시각',n.when],['수량',n.qty]].map(([a,b])=>`<div class="info-row"><span>${a}</span><b>${b}</b></div>`).join('')}</div><p>${n.detail}</p><p class="micro-note">연결 구조를 설명하는 가상 추적 이력입니다.</p>`;}
 else if(modal==='quality-hold'){const trace=traceLot(traceQuery,'down');body=`<div class="sheet-heading"><h2>품질 검토 · 출고 보류</h2>${close}</div><p><b>${esc(traceQuery)}</b>에서 품질 문제가 의심됩니다.<br>연결된 완제품 ${trace.lots.length}개 LOT와 납품처 ${trace.deliveries.length}곳을 확인해 주세요.</p><label class="form-label">검토 사유<textarea id="quality-reason" rows="3" placeholder="예: 원료 품질 이상 확인 필요"></textarea></label><div class="hint warning">${icon('info')}<span>데모 앱 내 출고만 보류합니다. 실제 ERP 상태 변경이나 고객사 통보는 수행하지 않습니다.</span></div>${btn('hold-confirm','품질 알림 생성 · 출고 보류 시연','action-primary')}`;}
 else if(modal==='reset'){body=`<div class="sheet-heading"><h2>시연을 처음부터 시작할까요?</h2>${close}</div><p>이 브라우저에 저장한 스캔·작업 이력·알림을 초기 시연 데이터로 되돌립니다. 실제 ERP에는 영향을 주지 않습니다.</p>${btn('reset-confirm','시연 데이터 초기화','action-primary')}`;}
 else if(modal==='choose-task'){body=`<div class="sheet-heading"><h2>스캔할 작업 선택</h2>${close}</div><p>작업 지시를 선택하면 해당 품목·LOT를 검수합니다.</p>${state.tasks.filter(x=>x.state!=='done'&&!x.allocated).map(x=>btn('choose-scan-task',`<div><b>${x.title}</b><small>${x.id} · ${kinds[x.kind].name}</small></div>${icon('chevron')}`,'warehouse-option',`data-id="${x.id}"`)).join('')||'<p>스캔할 작업이 없습니다. 작업 목록에서 확정 대기 건을 확인하세요.</p>'}`;}
 $('#modal-root').innerHTML=`<section class="sheet" role="dialog" aria-modal="true" aria-label="${modal==='scan'?'바코드 스캔':'작업 안내'}"><div class="sheet-handle"></div>${body}</section>`;if(modal==='scan')updateScanQueue();}
function design(){const el=$('#design-modal');el.hidden=false;el.innerHTML=`<section class="design-dialog" role="dialog" aria-modal="true" aria-label="ERP 로직 반영 및 설계">${btn('close-design',icon('close'),'close-design','aria-label="설계 닫기"')}<div class="eyebrow">ERP × MOBILE · DESIGN NOTES</div><h2>기존 업무를 잇는 모바일 앱</h2><span class="badge">로컬 소스 분석 기반 · 가상 연동</span><p>원자재·부자재·완제품을 같은 화면으로 단순화하되, ERP에서 재고를 반영하는 시점은 각각 구분했습니다. 실제 운영 DocumentRoot와 데이터는 검증되지 않았습니다.</p><div class="design-grid"><div><b>원자재 · M</b><p>원료 구매입고 → LOT 내역 등록 → 입고 확정 시 증가.<br>원료 LOT 출고 → 내역 등록 → 출고 확정 시 차감.</p></div><div><b>부자재 · S</b><p>부자재 구매입고와 출고를 별도로 관리.<br>창고·품목·LOT 기준 내역을 등록하고 확정할 때 재고 반영.</p></div><div><b>완제품 · P</b><p>주문·차량·LOT 출고 내역 저장 시 재고 차감.<br>출고 확정 시 상태 및 당시 단가 기록.<br>입고 시연은 위탁제품 입고 흐름.</p></div></div><h3>앱 화면 설계</h3><p>홈 → 입출고 작업 목록 → 작업 상세 → LOT 선택 / 바코드 스캔 → 검수 내역 저장 → 입출고 확정 → 완료.<br>재고 조회 → LOT 상세, 알림함 → 관련 작업 / 재고, 작업 이력 → 완료 건을 다시 볼 수 있습니다.</p><h3>연속 스캔 · 일괄 등록</h3><p>카메라로 라벨을 연속 인식해 스캔 보관함에 누적합니다. 고유 포장은 중복 차단하고, 상품·박스코드는 화면에서 사라진 뒤 다시 들어와야 다음 포장으로 셉니다. 마지막에 일괄 등록하며 서버로 건별 저장하지 않습니다.</p><h3>데모에서 추가한 정책</h3><ul><li>고유 포장 라벨의 중복·다른 품목·다른 LOT·초과 스캔 차단</li><li>전량 검수 후 저장, 재고 부족 및 소비기한 경과 출고 차단</li><li>입고 품질 체크 후 확정 (체크리스트와 품질 승인 연계는 협의 필요)</li><li>소비기한 7일 이내, 품목별 시연 기준 재고 미달 알림</li><li>앱 알림함·읽음 처리·작업 연결, 로컬 브라우저 상태 저장</li><li>중복 저장·확정 방지. 실제 서버에서는 멱등키·행 잠금이 필요</li></ul><h3>검증 범위</h3><p>현재 프로젝트의 malgeunmule 소스를 읽기 전용으로 분석했습니다. 실제 API·DB·로그인·운영 데이터·백그라운드 푸시는 연결하지 않았습니다. 카메라 인식은 사용자가 권한을 허용한 뒤 기기 안에서 처리합니다. 원자재 생산 수불·포장수량 환산은 별도 업무로 확인되었으며 이 데모의 원료 출고에 혼합하지 않았습니다.</p></section>`;el.querySelector('button').focus();}
function performScan(code,source='manual'){const r=scan(state,activeTask,code);scanMessage=r.message;scanError=!r.ok;persist();renderHeader();renderObserver();updateScanQueue();if(r.ok&&navigator.vibrate)navigator.vibrate(30);return r;}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const a=b.dataset.action;
 if(['home','tasks','stock','notices','history','erp','settings','trace','rules'].includes(a)){if(a==='tasks'){taskFilter='all';}if(a==='stock'){stockKind='all';stockWarehouse='전체 창고';}go(a);}
 else if(a==='task')openTask(b.dataset.id);
 else if(a==='back')go(screen==='detail'?'tasks':screen==='stock-detail'?'stock':'home');
 else if(a==='in-list'||a==='out-list'){taskFilter=a==='in-list'?'in':'out';go('tasks');}
 else if(a==='task-filter'){taskFilter=b.dataset.value;render();}
 else if(a==='task-kind'||a==='home-kind'){kindFilter=b.dataset.value;render();}
 else if(a==='stock-kind'){stockKind=b.dataset.value;render();}
 else if(a==='stock-detail'){activeStock=b.dataset.id;go('stock-detail');}
 else if(a==='scenario'){activeTask=b.dataset.id;openTask(activeTask);}
 else if(a==='scan'){const t=getTask();scanMessage='';scanError=false;if(screen!=='detail'||t.state==='done'||t.allocated)openModal('choose-task');else openModal('scan');}
 else if(a==='choose-scan-task'){activeTask=b.dataset.id;kindFilter=getTask().kind;screen='detail';modal='scan';scanMessage='';scanError=false;render();}
 else if(a==='scan-code')performScan(b.dataset.code);
 else if(a==='camera-start')startCamera();
 else if(a==='camera-stop'){stopCamera();cameraStatus='카메라 일시정지';$('#camera-status').textContent=cameraStatus;}
 else if(a==='batch-demo'){const t=getTask(),st=getStock(t);let added=0;for(let i=1;i<=t.qty/st.pack&&added<10;i++){const code=sampleCode(st.id,i);if(!t.scans.some(x=>x.code===code)){const r=performScan(code,'demo');if(r.ok)added++;else break;}}scanMessage=`시연 라벨 ${added}개를 연속 추가했습니다. 아직 ERP에 등록하지 않았습니다.`;updateScanQueue();}
 else if(a==='remove-scan'){const t=getTask();if(!t.allocated){t.scans.splice(Number(b.dataset.index),1);t.state=t.scans.length?'progress':'waiting';persist();updateScanQueue();renderObserver();}}
 else if(a==='work-kind'){kindFilter=b.dataset.value;go('home');}
 else if(a==='rules-samples'){window.open('labels.html?stock='+getTask().stockId,'_blank','noopener');}
 else if(a==='trace-stock'){traceQuery=getStock().lot;go('trace');}
 else if(a==='trace-direction'){traceDirection=b.dataset.value;render();}
 else if(a==='trace-sample'){traceQuery=b.dataset.value;render();}
 else if(a==='trace-node'){traceNodeId=b.dataset.id;openModal('trace-node');}
 else if(a==='quality-hold')openModal('quality-hold');
 else if(a==='hold-confirm'){const graph=traceLot(traceQuery,'down'),reason=$('#quality-reason')?.value.trim()||'품질 확인 요청';state.holds=[...new Set([...(state.holds||[]),traceQuery,...graph.lots])];notify(state,'error','품질 검토 · 출고 보류 요청',traceQuery+' / '+reason);log(state,'품질 검토 및 출고 보류 시연',traceQuery+' / 연결 완제품 '+graph.lots.length+'개 LOT','hold');modal='';render();toast('품질 알림을 생성하고 관련 LOT 출고를 보류했습니다.');}

 else if(a==='close-modal'){stopCamera();if(modal==='scan'){modal='';render();}else closeModal();}
 else if(a==='undo'){undo(state,activeTask);render();toast('최근 스캔 1건을 취소했습니다.');}
 else if(a==='save'){const r=saveAllocation(state,activeTask);render();toast(r.message,!r.ok);}
 else if(a==='confirm-open')openModal('confirm');
 else if(a==='confirm'){const r=confirm(state,activeTask);modal='';render();$('#app-content').scrollTop=0;toast(r.message,!r.ok);}
 else if(a==='lot-picker')openModal('lot');
 else if(a==='select-lot'){if(changeLot(state,activeTask,b.dataset.id)){modal='';render();toast('LOT를 변경했습니다. 선택한 LOT 라벨을 스캔하세요.');}}
 else if(a==='warehouse')openModal('warehouse');
 else if(a==='warehouse-stock'){stockWarehouse=b.dataset.value;stockKind='all';go('stock');}
 else if(a==='notice'){const n=state.notices.find(x=>x.id===b.dataset.id);n.read=true;if(n.stockId){activeStock=n.stockId;go('stock-detail');}else if(n.taskId)openTask(n.taskId);else render();}
 else if(a==='read-all'){state.notices.forEach(x=>x.read=true);render();toast('모든 알림을 읽음 처리했습니다.');}
 else if(a==='notice-filter'){noticeFilter=b.dataset.value;render();}
 else if(a==='simulate-notice'){const t=state.tasks.find(x=>x.state!=='done');if(t){notify(state,'task','ERP 작업 지시 알림이 도착했어요',`${t.title} · ${t.qty} ${getStock(t).unit}`,{taskId:t.id});log(state,'작업 지시 알림 수신',t.id,'receive');render();toast('새 작업 알림을 받았습니다. 알림함을 확인하세요.');}else toast('모든 작업이 완료되었습니다. 초기화 후 다시 시연하세요.');}
 else if(a==='toggle-alerts'){state.settings.alerts=!state.settings.alerts;render();toast(state.settings.alerts?'새 이벤트를 읽지 않은 알림으로 받습니다.':'새 이벤트는 읽은 알림으로 보관합니다.');}
 else if(a==='open-design')design();
 else if(a==='close-design'){$('#design-modal').hidden=true;}
 else if(a==='reset')openModal('reset');
 else if(a==='reset-confirm'){state=seed();activeTask=state.tasks[0].id;kindFilter='P';taskFilter='all';stockKind='all';stockWarehouse='전체 창고';noticeFilter='all';go('home');toast('새 시연을 시작합니다.');}
});
document.addEventListener('submit',e=>{if(e.target.id==='trace-form'){e.preventDefault();traceQuery=$('#trace-input').value.trim();render();}if(e.target.id==='scan-form'){e.preventDefault();performScan($('#barcode-input').value);$('#barcode-input').focus();}});
document.addEventListener('input',e=>{if(!e.isComposing&&(e.target.id==='task-search'||e.target.id==='stock-search')){query=e.target.value;const start=e.target.selectionStart;render();const input=$('#'+e.target.id);input.focus();input.setSelectionRange(start,start);}});
document.addEventListener('change',e=>{if(e.target.id==='measured-qty'){const n=Number(e.target.value);getTask().measuredQty=e.target.value!==''&&n>0?n:undefined;persist();}if(e.target.id==='location-select'){getTask().location=e.target.value;persist();}if(e.target.id==='quality-check'){getTask().quality=e.target.checked;persist();render();}if(e.target.id==='stock-warehouse'){stockWarehouse=e.target.value;render();}if(e.target.id==='vehicle-select'){getTask().vehicle=e.target.value;persist();renderObserver();}if(e.target.id==='vehicle-temp'){const n=Number(e.target.value);if(!Number.isFinite(n)||n< -30||n>50){toast('차량 온도는 -30~50℃ 범위로 입력해 주세요.',true);e.target.value=getTask().temp;}else{getTask().temp=e.target.value;persist();}}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(!$('#design-modal').hidden)$('#design-modal').hidden=true;else if(modal)closeModal();}if(e.key==='Tab'){const root=!$('#design-modal').hidden?$('#design-modal'):modal?$('#modal-root'):null;if(root){const nodes=[...root.querySelectorAll('button:not(:disabled),input:not(:disabled),a[href],select')],first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}}});
window.addEventListener('hashchange',()=>{const target=location.hash.slice(1);if(['home','tasks','stock','notices','trace','rules','settings','history','erp'].includes(target)&&target!==screen)go(target);});
window.addEventListener('pagehide',stopCamera);document.addEventListener('visibilitychange',()=>{if(document.hidden)stopCamera();});
$('#scenarios').innerHTML=[['OUT-1026-001','P','완제품 출고 검수','차량·LOT → 연속 스캔 → 일괄 등록'],['IN-1026-001','M','원자재 구매입고','수량 누적 → 일괄 등록 → 품질 확인'],['OUT-1026-002','S','부자재 LOT 출고','포장수량 누적 → 일괄 등록 → 확정']].map(([id,k,title,sub])=>btn('scenario',`<span class="${kinds[k].color}">${icon(kinds[k].icon)}</span><div><b>${title}</b><small>${sub}</small></div><em>↗</em>`,'scenario',`data-id="${id}"`)).join('');
function workPicker(){return `<div class="work-picker"><div class="work-picker-label">지금 어떤 업무를 하나요?</div><div class="work-picker-tabs">${['M','S','P'].map(k=>btn('work-kind',`${icon(kinds[k].icon)}<span>${kinds[k].name}</span>`,kindFilter===k?'selected '+kinds[k].color:'',`data-value="${k}"`)).join('')}</div><p>${workDescriptions[kindFilter]||'업무를 선택해 주세요.'}</p></div>`;}
function stepper(t){const index=t.allocated?3:t.scans.length?1:0;return `<div class="job-stepper">${['작업 확인','연속 스캔','일괄 등록','확정'].map((label,i)=>`<span class="${i<=index?'passed':''}"><i>${i<index?'✓':i+1}</i>${label}</span>`).join('')}</div>`;}
function scanSheet(t,s,close){const amount=Math.ceil(t.qty/s.pack);return `<div class="sheet-heading"><h2>연속 스캔 · 일괄 등록</h2>${close}</div><div class="camera-panel"><video id="camera-video" muted playsinline autoplay></video><div class="camera-overlay"><div class="camera-frame"></div><span id="camera-status">카메라 대기 · 시작 버튼을 눌러 주세요</span></div></div><div class="camera-actions">${btn('camera-start',icon('scan')+' 카메라 시작','action-primary')}${btn('camera-stop','중지','secondary-btn')}</div><p class="camera-help">라벨을 차례로 비추세요. 인식할 때마다 보관함에 누적됩니다.<br>상품·박스코드는 화면 밖으로 뺐다가 다시 비춰 주세요.</p><div class="scan-feedback" id="scan-feedback" role="status">${esc(scanMessage||'인식 결과를 모은 후 한 번에 등록합니다.')}</div><div id="batch-summary"></div><div class="camera-queue" id="scan-queue"></div><form id="scan-form" class="scan-form"><label for="barcode-input">스캐너 · 코드 직접 입력</label><div class="scan-input"><input id="barcode-input" placeholder="예: ${sampleCode(s.id,1)}" autocomplete="off"><button type="submit">추가</button></div></form>${s.unit==='kg'?`<label class="measured-label">상품코드 스캔 시 실측 중량 (kg)<input id="measured-qty" type="number" min="0.001" step="0.001" placeholder="예: 25" value="${esc(t.measuredQty??'')}"></label>`:''}<details class="demo-labels"><summary>카메라 없이 시연용 라벨로 체험</summary><div class="sample-grid">${Array.from({length:Math.min(amount,6)},(_,i)=>btn('scan-code',sampleCode(s.id,i+1),'',`data-code="${sampleCode(s.id,i+1)}"`)).join('')}</div>${amount>6?btn('batch-demo','다음 10개 라벨 연속 추가 (시연)','secondary-btn'):''}<div class="error-samples">${btn('scan-code','미등록 코드','',`data-code="UNKNOWN"`)}${btn('scan-code','다른 품목','',`data-code="${sampleCode(s.kind==='P'?'M1':'P1',99)}"`)}${btn('scan-code','초과 스캔 확인','',`data-overflow data-code="BOX-${s.item}" ${quantity(t)===t.qty?'':'disabled'}`)}</div></details><a class="scan-label-link" href="labels.html?stock=${s.id}" target="_blank" rel="noreferrer">촬영할 샘플 라벨 열기 · 인쇄 ↗</a>${btn('close-modal','스캔 보관함 확인 → 일괄 등록','action-primary')}<p class="micro-note">카메라 영상은 서버로 전송하지 않습니다.<br>현재 주문의 품목·LOT·포장수량과 비교합니다.</p>`;}
function updateScanQueue(){if(modal!=='scan')return;const t=getTask(),st=getStock(t);const overflow=document.querySelector('[data-overflow]');if(overflow)overflow.disabled=quantity(t)!==t.qty;const feedback=$('#scan-feedback');if(feedback){feedback.textContent=scanMessage||'인식 결과를 보관함에 모은 후 한 번에 등록합니다.';feedback.className='scan-feedback'+(scanError?' error':'');}$('#batch-summary').innerHTML=`<div class="batch-summary"><span>미등록 보관함 <b>${t.scans.length}건</b></span><strong>${quantity(t)} <small>/ ${t.qty} ${st.unit}</small></strong></div><div class="progress-track"><div style="width:${quantity(t)/t.qty*100}%"></div></div>`;$('#scan-queue').innerHTML=t.scans.slice(-8).map((x,i)=>`<div class="queue-item"><div><b>${esc(x.code)}</b><small>${x.mode==='sku'?'상품 단위':x.mode==='box'?'포장 단위':'고유 포장'} · +${x.qty} ${st.unit}</small></div>${btn('remove-scan',icon('close'),'icon-btn',`data-index="${t.scans.length>8?t.scans.length-8+i:i}" aria-label="${esc(x.code)} 스캔 삭제"`)}</div>`).join('')||'<div class="queue-empty">아직 스캔한 라벨이 없습니다.</div>';}
function stopCamera(){cameraSession?.stop();cameraSession=null;const status=document.querySelector('#camera-status');if(status)status.textContent='카메라 중지 · 다시 시작할 수 있습니다.';}
async function startCamera(){stopCamera();cameraSession=new ContinuousScanner({onCodes:codes=>{if(modal!=='scan')return;for(const code of codes)performScan(code,'camera');},onStatus:text=>{cameraStatus=text;const el=$('#camera-status');if(el)el.textContent=text;},onError:message=>{scanMessage=message;scanError=true;const el=$('#camera-status');if(el)el.textContent='카메라 연결 확인 필요';updateScanQueue();}});await cameraSession.start($('#camera-video'));}
function tracePage(){const graph=traceLot(traceQuery,traceDirection);const currentRows=state.history.filter(h=>h.direction==='out'&&graph.nodes.some(n=>n.lot===h.lot));return `<div class="list-top"><h2>LOT 이력 추적</h2><span>구매 → 생산 → 납품</span></div><p class="trace-intro">LOT 하나로 어디서 들어와, 무엇에 쓰이고,<br>어디로 납품됐는지 확인하세요.</p><form id="trace-form" class="trace-search"><label for="trace-input">추적할 LOT 번호</label><div class="scan-input"><input id="trace-input" value="${esc(traceQuery)}" placeholder="LOT 번호 입력"><button type="submit">조회</button></div></form><div class="trace-samples">${[['RM-261020','원자재'],['SM-261022','부자재'],['FP-261024-A','완제품']].map(([v,label])=>btn('trace-sample',label+' 예시',traceQuery===v?'selected':'',`data-value="${v}"`)).join('')}</div><div class="segmented">${[['both','전체 연결'],['up','입고까지 역추적'],['down','납품까지 추적']].map(([v,label])=>btn('trace-direction',label,traceDirection===v?'selected':'',`data-value="${v}"`)).join('')}</div><div class="trace-status"><span>가상 연결 이력</span><b>${esc(traceQuery)}</b></div>${graph.nodes.length?`<div class="stock-summary"><div><small>연결 완제품 LOT</small><strong>${graph.lots.length}<span>개</span></strong></div><div><small>확인할 납품처</small><strong>${graph.deliveries.length}<span>곳</span></strong></div></div><div class="trace-timeline">${graph.nodes.map(n=>btn('trace-node',`<span class="trace-marker ${kinds[n.kind].color}">${icon(n.type==='deliver'?'truck':n.type==='receive'?'in':n.type==='process'?'settings':'box')}</span><div><small>${n.department} · ${n.when}</small><b>${n.title}</b><strong>${n.item}</strong><p>${n.lot} · ${n.qty}</p></div>${icon('chevron')}`,'trace-node',`data-id="${n.id}"`)).join('')}</div>${currentRows.length?`<h3 class="trace-heading">이번 시연의 확정 출고</h3>${currentRows.map(h=>`<div class="app-erp-log"><h4>${h.id}</h4><p>${h.lot} · ${h.qty} ${h.unit} / ${h.time}</p></div>`).join('')}`:''}<div class="trace-relations"><b>LOT 연결 관계</b>${graph.edges.map(([a,b])=>{const x=traceNodes.find(n=>n.id===a),y=traceNodes.find(n=>n.id===b);return `<p>${x.lot} <span>→</span> ${y.lot}<small>${x.title} → ${y.title}</small></p>`;}).join('')}</div>${btn('quality-hold',icon('warning')+' 품질 검토 · 출고 보류 시연','secondary-btn')}<div class="hint">${icon('info')}<span>ERP에 LOT·생산 추적 화면이 있습니다. 이 화면의 입고-투입-생산-납품 연결과 수량은 설계용 가상 이력이며 실제 데이터 연결은 검증되지 않았습니다.</span></div>`:`<div class="empty">이 LOT의 연결 이력이 없습니다.<p>날짜나 품목이 같아도 연결을 추정하지 않습니다.<br>위의 예시 LOT를 선택해 추적 흐름을 체험하세요.</p></div>`}`;}
function rulesPage(){return `<div class="list-top"><h2>라벨·수량 기준</h2><span>ERP 확인 / 제안 구분</span></div><div class="hint">${icon('info')}<span>아래 ERP 화면과 필드는 로컬 코드에서 확인했습니다. 실제 운영 바코드 값·인쇄 라벨은 검증하지 않았습니다.</span></div><div class="rules-card"><span class="task-type amber">원자재 · 중량</span><h3>품목코드와 kg를 구분해요</h3><p>ERP 원료 관리: 바코드, 단위, 패킹(kg).<br>상품코드만 스캔하면 중량을 알 수 없으므로 실측 kg 입력이 필요합니다. 고유 포장 라벨은 연결된 포장 중량을 사용합니다.</p></div><div class="rules-card"><span class="task-type blue">부자재 · 포장수량</span><h3>코드와 패킹을 확인해요</h3><p>ERP 부자재 관리: 부자재코드, 패킹, 단위.<br>상품코드 1회는 1 EA, 포장코드 1회는 연결된 패킹 수량으로 시연합니다. 실제 패킹 환산은 현장 확인이 필요합니다.</p></div><div class="rules-card"><span class="task-type teal">완제품 · SKU / BOX</span><h3>낱개와 BOX를 나눠 세어요</h3><p>ERP 제품 관리: 바코드, 박스입수.<br>상품 바코드 1회는 1 EA, BOX 코드는 박스입수만큼 가산합니다. 차량·LOT 기준으로 출고를 검수합니다.</p></div><div class="rules-card"><h3>실제 ERP에 있는 라벨 화면</h3><ul><li>기초정보 → 원료·부자재·제품 관리</li><li>생산 → 원료 계량 바코드 생성</li><li>생산 → 벌크 라벨 출력 (Code 128)</li><li>생산 → 포장 라벨 출력 (EAN-13)</li></ul><p>별도의 고유 포장 라벨 마스터, 전사 공통 바코드 구성 및 개별 포장 식별 체계는 확인되지 않았습니다. 제품 바코드 필드 사용도 화면별로 달라 현장 라벨 대조가 필요합니다.</p></div><div class="rules-card"><h3>이 데모의 스캔 규칙</h3><dl><dt>상품 바코드 · 숫자 13자리</dt><dd>시연용 EAN-13 / 품목만 식별 / 포장 고유번호 없음</dd><dt>BOX-FP-001 등 포장코드</dt><dd>Code 128 / 품목·포장수량 연결 / LOT는 작업에서 선택</dd><dt>PK-P1-0001 등 고유 포장</dt><dd>Code 128 / 시연 마스터의 품목·LOT·수량·포장 ID에 연결</dd></dl><p>상품·BOX 코드는 다음 실물을 비추기 위해 화면에서 빼고 다시 비춰야 가산합니다. 고유 포장은 같은 작업 또는 같은 방향의 다른 등록 작업에서 중복 처리하지 않습니다.</p></div><a href="labels.html" target="_blank" rel="noreferrer" class="action-primary">촬영할 샘플 라벨 열기 · 인쇄 ↗</a><p class="micro-note">모든 샘플 바코드는 신규 제안 규칙의 가상 라벨입니다.</p>`;}

const initial=location.hash.slice(1);if(['home','tasks','stock','notices','settings','erp','history','trace','rules'].includes(initial))screen=initial;render();

